require_once __DIR__.'/backend/authorization.php';require_once __DIR__.'/backend/db.php';require_once __DIR__.'/backend/csrf.php';requireSuperAdmin();$message='';$type='success';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=(string)($_POST['action']??'');if($action==='create'){$name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8||!preg_match('/[A-Z]/',$pw)||!preg_match('/[a-z]/',$pw)||!preg_match('/[0-9]/',$pw)||!preg_match('/[^A-Za-z0-9]/',$pw)){$message='Enter a valid name, email, and strong temporary password.';$type='error';}else{$c=$conn->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$c->bind_param('s',$email);$c->execute();if($c->get_result()->num_rows){$message='That email already exists.';$type='error';}else{$hash=password_hash($pw,PASSWORD_DEFAULT);$role='admin';$status='active';$s=$conn->prepare('INSERT INTO users(full_name,email,password_hash,role,account_status,email_verified_at) VALUES (?,?,?,?,?,NOW())');$s->bind_param('sssss',$name,$email,$hash,$role,$status);$s->execute();$id=(int)$conn->insert_id;$a=$conn->prepare("INSERT INTO auth_identities(user_id,provider,provider_user_id) VALUES (?,'password',?)");$a->bind_param('is',$id,$email);$a->execute();audit($conn,'admin_created','user',$id);$message='Front Desk Administrator created.';}}}elseif($action==='status'){$id=(int)($_POST['admin_id']??0);$status=(string)($_POST['account_status']??'');if($id>0&&in_array($status,['active','suspended'],true)){$u=$conn->prepare("UPDATE users SET account_status=? WHERE id=? AND role='admin'");$u->bind_param('si',$status,$id);$u->execute();audit($conn,'admin_status_'.$status,'user',$id);$message='Administrator status updated.';}}}
$admins=$conn->query("SELECT id,full_name,email,role,account_status,last_login_at,created_at FROM users WHERE role IN ('admin','super_admin') ORDER BY role='super_admin' DESC,full_name");
?>
