unt_status'])?></span></td><td><?=h($a['last_login_at']?:'—')?></td><td><?php if($a['role']==='super_admin'):?><span class="muted">Protected</span><?php else:?><form method="POST" class="inline-form"><?=csrfInput()?><input type="hidden" name="action" value="status"><input type="hidden" name="admin_id" value="<?= (int)$a['id']?>"><input type="hidden" name="account_status" value="<?=$a['account_status']==='active'?'suspended':'active'?>"><button class="btn <?=$a['account_status']==='active'?'danger':'approve'?> tiny"><?=$a['account_status']==='active'?'Suspend':'Reactivate'?></button></form><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></section></div></main></body></html>
